{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Bepotastine, a zwitterionic piperidine antihistamine with a carboxylic acid, showed only 16.6% brain H1 receptor occupancy by PET in humans, indicating low BBB permeability; this is the highest-transfer analogue and shares the query's ionizable piperidine/carboxylic acid zwitterionic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Enalapril, another ionizable acid/amine-containing molecule, produced only low brain and CSF levels after acute oral or intravenous dosing in rats, supporting poor CNS access for zwitterionic/acidic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Pitolisant, a lipophilic basic amine without an acidic group, showed good oral absorption and brain penetration in rodents; this is contradictory evidence but has low transfer and lacks the query's zwitterionic acid/amine motif.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "A lipophilic piperazine amide without an ionizable acid showed a brain:plasma ratio >2 in rats, supporting CNS penetration; low transfer and absence of the acid/zwitterion limit its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: fail. The strongest transferable evidence comes from zwitterionic acid/amine molecules such as bepotastine and enalapril, which show low brain/CSF exposure. The query is fully ionized at physiological pH, zwitterionic, and has low predicted passive permeability. Lipophilic basic amine analogues that penetrate the brain are structurally dissimilar and have low transfer scores, so they do not override the direct zwitterion evidence.",
  "evidence_gaps": [
    "No direct brain, plasma, CSF, or receptor-occupancy data for the exact query molecule.",
    "No P-gp/BCRP or other efflux-transporter data for the query.",
    "No assessment of possible active uptake transporters that could mitigate low passive permeability.",
    "In silico logD and pKa estimates may have uncertainty.",
    "Most brain-penetrant analogues have low transfer scores and lack the query's zwitterionic acid/amine feature."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

